 $recorded=$pdo->query('SELECT version FROM app_migrations')->fetchAll(PDO::FETCH_COLUMN);$missing=false;foreach($recorded as $version)if((int)$version>430)throw new RuntimeException('Neuere Datenbankversion: kein Downgrade zulässig.');
 $frequencyShape=$pdo->query("SHOW COLUMNS FROM recurring_jobs LIKE 'frequency'")->fetch(PDO::FETCH_ASSOC);$allowedShapes=["enum('weekly','biweekly','monthly','quarterly','seasonal')","enum('weekly','biweekly','monthly','quarterly','seasonal','daily')"];if(!$frequencyShape||!in_array($frequencyShape['Type'],$allowedShapes,true)||$frequencyShape['Null']!=='NO'||$frequencyShape['Default']!=='weekly'||$pdo->query("SELECT id FROM recurring_jobs WHERE frequency NOT IN ('weekly','biweekly','monthly','quarterly','seasonal','daily') LIMIT 1")->fetchColumn())throw new RuntimeException('Unbekannter/beschädigter Rhythmustyp: keine automatische ENUM-Änderung.');
 foreach($steps as $v=>$marker){if(!is_file(__DIR__.'/migration_v'.$v.'.sql'))throw new RuntimeException('Migrationsdatei fehlt.');if(!in_array($marker,$recorded,true))$missing=true;elseif($missing)throw new RuntimeException('Migrationshistorie hat eine Lücke; Struktur manuell prüfen.');}
