 $frequency=$pdo->query("SHOW COLUMNS FROM recurring_jobs LIKE 'frequency'")->fetch(PDO::FETCH_ASSOC);if(!$frequency||!str_contains($frequency['Type'],"'daily'"))throw new RuntimeException('v350-Tagesintervall fehlt; protokollierte Struktur prüfen.');
 if((int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version IN ('230_mail_security','240_finance_basis','250_documents','260_pdf_originals','270_operations','280_receivables','290_finance_recurrences','300_cash_assets','310_estate_core','320_estate_settlements','330_mail_recovery','340_v1','350_final','360_waste_connections','370_bank_connections')")->fetchColumn()!==15)throw new RuntimeException('Migration unvollständig.');
 if(!$has380)gszMigrate380($pdo);if(!(int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='380_zentrale'")->fetchColumn())throw new RuntimeException('Migration 380 unvollständig.');
